using System;using System.Diagnostics;using System.IO;using System.Threading.Tasks;using System.Windows.Forms;
[assembly: System.Reflection.AssemblyVersion("1.0.0.0")]
[assembly: System.Reflection.AssemblyFileVersion("1.0.0.0")]
namespace LocalChatRail {static class Setup {
 [STAThread] static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);bool uninstall=Path.GetFileNameWithoutExtension(Application.ExecutablePath).Equals("Uninstall",StringComparison.OrdinalIgnoreCase);string action=uninstall?"卸载":"安装";var dialog=new RailDialog("正在"+action,"请稍候…");dialog.Busy=true;dialog.Shown+=async(s,e)=>{try{string output=await Task.Run(()=>{var info=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"System32\\WindowsPowerShell\\v1.0\\powershell.exe"),"-NoProfile -ExecutionPolicy Bypass -File \""+Path.Combine(AppDomain.CurrentDomain.BaseDirectory,uninstall?"Uninstall.ps1":"Install.ps1")+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true};using(var p=Process.Start(info)){var error=p.StandardError.ReadToEndAsync();var text=p.StandardOutput.ReadToEndAsync();p.WaitForExit();Task.WaitAll(error,text);if(p.ExitCode!=0)throw new InvalidOperationException(error.Result);return text.Result;}});dialog.SetTitle(action+"成功");dialog.UpdateText(uninstall?"导航工具已移除。":"已创建 Chat Navigation Rail 开始菜单快捷方式。");}catch(Exception ex){dialog.SetTitle(action+"未完成");dialog.UpdateText(ex.Message.Length>600?ex.Message.Substring(0,600):ex.Message);}finally{dialog.Busy=false;}};Application.Run(dialog);}
}}
